/** Lower-cased names and ids that resolve to a vendor glyph. */
const VENDOR_ALIASES: ReadonlyArray<readonly [UsageCreditVendor, ReadonlyArray<string>]> = [
  ["openrouter", ["openrouter", "open-router"]],
  ["deepseek", ["deepseek", "deep-seek"]],
  ["venice", ["venice", "venice-ai", "veniceai"]],
  ["openai", ["openai", "open-ai", "chatgpt", "codex"]],
  ["anthropic", ["anthropic", "claude"]],
  ["google", ["google", "gemini", "google-ai", "googleai", "vertex"]],
  ["xai", ["xai", "x-ai", "grok"]],
  ["mistral", ["mistral", "mistralai", "mistral-ai"]],
  ["groq", ["groq"]],
  ["together", ["together", "togetherai", "together-ai"]],
  ["fireworks", ["fireworks", "fireworksai", "fireworks-ai"]],
  ["perplexity", ["perplexity", "pplx"]],
  ["moonshot", ["moonshot", "kimi", "moonshotai", "moonshot-ai"]],
  ["zai", ["zai", "z.ai", "z-ai", "zhipu", "zhipuai", "zhipu-ai", "bigmodel", "glm"]],
  ["cerebras", ["cerebras"]],
  ["cohere", ["cohere"]],
  [
    "alibaba",
    ["alibaba", "alibaba cloud", "qwen", "dashscope", "alibabacloud", "alibaba-cloud", "aliyun"],
  ],
];

const VENDOR_BY_ALIAS = new Map<string, UsageCreditVendor>(
  VENDOR_ALIASES.flatMap(([vendor, aliases]) => aliases.map((alias) => [alias, vendor] as const)),
);

function normalizeVendorName(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[\s_]+/g, "-");
}

/**
 * Resolves the glyph for a credit balance. An explicit `icon` from the endpoint wins; otherwise
 * the balance id (minus a currency suffix such as `deepseek-USD`) and then the label are tried.
 * Returns undefined when no vendor matches, so callers show an initials badge instead.
 */
export function usageCreditVendor(balance: {
  readonly id: string;
  readonly label: string;
  readonly icon?: string | undefined;
}): UsageCreditVendor | undefined {
  const candidates = [balance.icon, balance.id, balance.label].flatMap((value) => {
    if (!value) return [];
    const normalized = normalizeVendorName(value);
    const withoutCurrency = normalized.replace(/-[a-z]{3}$/, "");
    return withoutCurrency === normalized ? [normalized] : [normalized, withoutCurrency];
  });
  for (const candidate of candidates) {
    const vendor = VENDOR_BY_ALIAS.get(candidate);
    if (vendor) return vendor;
  }
  return undefined;
}
